import 'dart:convert';
import 'dart:typed_data';
import 'package:supabase_flutter/supabase_flutter.dart';
import '../domain/commission.dart';
class CommissionRepository {
 CommissionRepository({SupabaseClient? client}):_client=client??Supabase.instance.client;final SupabaseClient _client;
 static const _columns='id,employee_id,team_id,period_month,amount,currency,status,source_file_name,confirmed_at,confirmation_note,created_at,updated_at,employee:users!commissions_employee_id_fkey(name,agent_code),team:teams!commissions_team_id_fkey(name)';
 Future<List<CommissionRecord>> list({DateTime? month})async{var q=_client.from('commissions').select(_columns);if(month!=null){final m=DateTime(month.year,month.month,1).toIso8601String().substring(0,10);q=q.eq('period_month',m);}final rows=await q.order('period_month',ascending:false).order('created_at',ascending:false);return rows.map((r)=>CommissionRecord.fromJson(Map<String,dynamic>.from(r))).toList();}
 Future<CommissionRecord> get(String id)async{final row=await _client.from('commissions').select(_columns).eq('id',id).single();return CommissionRecord.fromJson(Map<String,dynamic>.from(row));}
 Future<void> confirm(String id,CommissionStatus status,{String? note})async{await _client.rpc('confirm_commission',params:{'p_commission_id':id,'p_status':status.databaseValue,'p_note':note});}
 Future<void> updateAmount(String id,double amount,{required String note})async{if(!amount.isFinite||amount<0)throw const FormatException('Amount must be zero or greater.');await _client.from('commissions').update({'amount':amount,'owner_note':note.trim(),'updated_by':_client.auth.currentUser!.id}).eq('id',id);}
 Future<void> addComment(String id,String text,{required bool shareWithTeam})async{final actor=await _client.from('users').select('id').eq('auth_user_id',_client.auth.currentUser!.id).single();await _client.from('commission_comments').insert({'commission_id':id,'author_user_id':actor['id'],'comment':text.trim(),'shared_with_team':shareWithTeam});}
 Future<List<Map<String,dynamic>>> comments(String id)async{final rows=await _client.from('commission_comments').select('id,comment,shared_with_team,created_at,author:users!commission_comments_author_user_id_fkey(name,agent_code)').eq('commission_id',id).order('created_at');return rows.map((r)=>Map<String,dynamic>.from(r)).toList();}
 Future<List<Map<String,dynamic>>> history(String id)async{final rows=await _client.from('commission_history').select('id,event_type,old_record,new_record,created_at,actor:users!commission_history_actor_user_id_fkey(name,agent_code)').eq('commission_id',id).order('created_at',ascending:false);return rows.map((r)=>Map<String,dynamic>.from(r)).toList();}
 Future<List<CommissionComplaint>> complaints()async{final rows=await _client.from('commission_complaints').select('*').order('created_at',ascending:false);return rows.map((r)=>CommissionComplaint.fromJson(Map<String,dynamic>.from(r))).toList();}
 Future<void> submitComplaint({required CommissionRecord commission,required String type,required String message,double? expectedAmount,Uint8List? evidence,String? fileName})async{String? path;if(evidence!=null){final authId=_client.auth.currentUser!.id;path='${commission.id}/$authId/${DateTime.now().microsecondsSinceEpoch}_${(fileName??'evidence.jpg').replaceAll(RegExp(r'[^A-Za-z0-9._-]'),'_')}';await _client.storage.from('commission-evidence').uploadBinary(path,evidence,fileOptions:FileOptions(contentType:_contentType(fileName),upsert:false));}final actor=await _client.from('users').select('id').eq('auth_user_id',_client.auth.currentUser!.id).single();await _client.from('commission_complaints').insert({'commission_id':commission.id,'employee_id':actor['id'],'complaint_type':type,'message':message.trim(),'expected_amount':expectedAmount,'screenshot_path':path});}
 Future<String> signedEvidenceUrl(String path)async=>_client.storage.from('commission-evidence').createSignedUrl(path,300);
 Future<Map<String,dynamic>> statistics({DateTime? month})async{final rows=await list(month:month);var total=0.0,confirmed=0.0,pending=0.0,issues=0;for(final r in rows){total+=r.amount;if(r.status==CommissionStatus.confirmed)confirmed+=r.amount;if(r.status==CommissionStatus.pending)pending+=r.amount;if(r.status==CommissionStatus.notReceived||r.status==CommissionStatus.wrongAmount)issues++;}return {'records':rows.length,'total':total,'confirmed':confirmed,'pending':pending,'issues':issues};}
 Future<int> uploadMonthlyCsv({required Uint8List bytes,required String fileName,required DateTime month})async{final records=_parseCsv(utf8.decode(bytes,allowMalformed:false));if(records.length<2)throw const FormatException('CSV must include a header and at least one commission row.');final headers=records.first.map((v)=>v.trim().toLowerCase()).toList();final ci=headers.indexOf('employee_code'),ai=headers.indexOf('amount'),curi=headers.indexOf('currency');if(ci<0||ai<0)throw const FormatException('CSV headers must include employee_code,amount. Optional: currency.');final employees=await _client.from('users').select('id,agent_code,team_id').eq('status','active').eq('employment_status','ACTIVE').eq('id_approval_status','APPROVED');final byCode={for(final e in employees)e['agent_code'].toString().toUpperCase():e};final period=DateTime(month.year,month.month,1).toIso8601String().substring(0,10);final payload=<Map<String,dynamic>>[];final seen=<String>{};for(final row in records.skip(1)){if(row.every((v)=>v.trim().isEmpty))continue;if(row.length<=ai||row.length<=ci)throw const FormatException('A CSV row is missing required values.');final code=row[ci].trim().toUpperCase(),emp=byCode[code];if(emp==null)throw FormatException('Unknown or inactive employee code: $code');if(!seen.add(code))throw FormatException('Duplicate employee code in file: $code');final amount=double.tryParse(row[ai].trim().replaceAll(',',''));if(amount==null||!amount.isFinite||amount<0)throw FormatException('Invalid amount for $code');final currency=curi>=0&&row.length>curi&&row[curi].trim().isNotEmpty?row[curi].trim().toUpperCase():'LKR';if(!RegExp(r'^[A-Z]{3}$').hasMatch(currency))throw FormatException('Invalid currency for $code');payload.add({'employee_id':emp['id'],'team_id':emp['team_id'],'period_month':period,'amount':amount,'currency':currency,'source_file_name':fileName,'created_by':_client.auth.currentUser!.id,'updated_by':_client.auth.currentUser!.id});}if(payload.isEmpty)throw const FormatException('CSV contains no commission rows.');await _client.from('commissions').upsert(payload,onConflict:'employee_id,period_month');return payload.length;}
 List<List<String>> _parseCsv(String source){final rows=<List<String>>[];var row=<String>[];var cell=StringBuffer();var quoted=false;for(var i=0;i<source.length;i++){final c=source[i];if(c=='"'){if(quoted&&i+1<source.length&&source[i+1]=='"'){cell.write('"');i++;}else{quoted=!quoted;}}else if(c==','&&!quoted){row.add(cell.toString());cell=StringBuffer();}else if((c=='\n'||c=='\r')&&!quoted){if(c=='\r'&&i+1<source.length&&source[i+1]=='\n')i++;row.add(cell.toString());rows.add(row);row=<String>[];cell=StringBuffer();}else{cell.write(c);}}if(quoted)throw const FormatException('CSV has an unclosed quote.');if(cell.isNotEmpty||row.isNotEmpty){row.add(cell.toString());rows.add(row);}return rows;}
 String _contentType(String? name){final n=(name??'').toLowerCase();if(n.endsWith('.png'))return 'image/png';if(n.endsWith('.webp'))return 'image/webp';if(n.endsWith('.pdf'))return 'application/pdf';return 'image/jpeg';}
}
